// Re-exported from @mrdoge/react. Fetched once per unique params, shared
// by every component asking for the same ones; a later mount reads the
// cache instead of refetching.
export { useTrendingMatches, type UseTrendingMatchesOptions } from "@mrdoge/react"

import "server-only"
import { NextResponse } from "next/server"
import { MrDoge } from "@mrdoge/node"

let client: MrDoge | null = null

function getClient() {
  if (!client) {
    client = new MrDoge({ apiKey: process.env.MRDOGE_ODDS_API_KEY! })
  }
  return client
}

export async function POST() {
  const { token, expiresAt } = await getClient().tokens.create()
  return NextResponse.json({ token, expiresAt })
}
